import com.liferay.portal.kernel.log.LogFactoryUtil;
import com.liferay.portal.kernel.model.Role;
import com.liferay.portal.kernel.model.User;
import com.liferay.portal.kernel.model.role.RoleConstants;
import com.liferay.portal.kernel.service.RoleLocalService;
import com.liferay.portal.kernel.util.PortalUtil;

import java.util.List;
import java.util.Map;

import javax.servlet.http.HttpSession;

import org.osgi.service.component.annotations.Activate;
import org.osgi.service.component.annotations.Component;
import org.osgi.service.component.annotations.Modified;
import org.osgi.service.component.annotations.Reference;

import it.servizidigitali.portal.configuration.RoleSelectionConfiguration;
import it.servizidigitali.portal.constant.ServiziDigitaliPortalConstants;

/**
 *
 * @author pindi
 *
 */
@Component(immediate = true, //
		property = { "key=login.events.post" }, //
		service = LifecycleAction.class, //
		configurationPid = "it.servizidigitali.portal.configuration.RoleSelectionConfiguration"//
)
public class LoginPostAction implements LifecycleAction {

	public static final Log log = LogFactoryUtil.getLog(LoginPostAction.class);

	private volatile RoleSelectionConfiguration roleSelectionConfiguration;

	@Reference
	private RoleLocalService roleLocalService;

	@Activate
	@Modified
	private void activate(Map<String, Object> props) {
		roleSelectionConfiguration = ConfigurableUtil.createConfigurable(RoleSelectionConfiguration.class, props);
	}

	@Override
	public void processLifecycleEvent(LifecycleEvent lifecycleEvent) throws ActionException {
		try {
			User user = PortalUtil.getUser(lifecycleEvent.getRequest());
			if (user != null) {
				HttpSession session = lifecycleEvent.getRequest().getSession();
				session.setAttribute(ServiziDigitaliPortalConstants.CURRENT_USER_SCREEN_NAME, user.getScreenName());

				resolveActiveRole(user, session);
			}
		}
		catch (PortalException e) {
			log.error("processLifecycleEvent :: " + e.getMessage(), e);
		}
	}

	/**
	 * Determina il profilo attivo dell'utente e lo scrive in sessione.
	 *
	 * <ul>
	 * <li>Administrator: bypass, nessun attributo impostato (navigazione completa).</li>
	 * <li>Doppio ruolo (cittadino + operatore-backoffice): {@code HAS_DUAL_ROLE=true}, {@code ACTIVE_ROLE=OPERATORE} (default).</li>
	 * <li>Solo operatore: {@code ACTIVE_ROLE=OPERATORE}.</li>
	 * <li>Solo cittadino: {@code ACTIVE_ROLE=CITTADINO}.</li>
	 * </ul>
	 */
	private void resolveActiveRole(User user, HttpSession session) {
		if (roleSelectionConfiguration == null || !roleSelectionConfiguration.switchProfiloAttivo()) {
			return;
		}

		String ruoloOperatore = roleSelectionConfiguration.ruoloOperatoreBackoffice();
		String ruoloCittadino = roleSelectionConfiguration.ruoloCittadino();

		boolean isOperatore = false;
		boolean isCittadino = false;
		boolean isAdministrator = false;

		List<Role> userRoles = roleLocalService.getUserRoles(user.getUserId());
		if (userRoles != null) {
			for (Role role : userRoles) {
				String roleName = role.getName();
				if (RoleConstants.ADMINISTRATOR.equals(roleName)) {
					isAdministrator = true;
				}
				else if (roleName.equals(ruoloOperatore)) {
					isOperatore = true;
				}
				else if (roleName.equals(ruoloCittadino)) {
					isCittadino = true;
				}
			}
		}

		// Administrator: bypass dello switch, navigazione completa.
		if (isAdministrator) {
			return;
		}

		boolean hasDualRole = isOperatore && isCittadino;
		session.setAttribute(ServiziDigitaliPortalConstants.HAS_DUAL_ROLE, hasDualRole);

		if (isOperatore) {
			// Doppio ruolo o solo operatore: il default attivo è OPERATORE.
			session.setAttribute(ServiziDigitaliPortalConstants.ACTIVE_ROLE, ServiziDigitaliPortalConstants.ROLE_OPERATORE);
		}
		else if (isCittadino) {
			session.setAttribute(ServiziDigitaliPortalConstants.ACTIVE_ROLE, ServiziDigitaliPortalConstants.ROLE_CITTADINO);
		}
	}
}

